functions._atsRenderAll:
function _atsRenderAll() {
  var hasTpl = !!_atsCurrent();
  var body = document.getElementById("atsBody");
  if (!body) return;
  if (!hasTpl) {
    body.innerHTML =
      '<div class="_ats_empty_state">' +
        '<div class="_ats_empty_icon">📋</div>' +
        '<div class="_ats_empty_title">No template selected</div>' +
        '<div class="_ats_empty_sub">Open the picker above to load one, or create a new template to start.</div>' +
      '</div>';
    _atsRenderCurrent();
    return;
  }
  body.innerHTML =
    // Word ↔ Template
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📝 Word ↔ Template</div>' +
      '</div>' +
      '<div class="_ats_section_hint">' +
        'Edit the template <b>in Word</b>. Load pulls the saved content into the doc (snapshots first). Save captures the current doc body into this template.' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsLoadInto">📥 Load into Word</button>' +
        '<button class="_ats_btn _ats_btn_success" id="atsSaveFrom">💾 Save Word doc</button>' +
      '</div>' +
    '</div>' +

    // Test safety
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🧪 Test safety</div>' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsSnap">📸 Snapshot doc</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRestore">↩ Restore</button>' +
      '</div>' +
      '<div class="_ats_section_hint" style="margin-top:6px; margin-bottom:0;">' +
        'Snapshot the doc body before risky edits. Restore reverts back.' +
      '</div>' +
    '</div>' +

    // Logic insertion at cursor (Word)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">➕ Insert logic at cursor</div>' +
      '</div>' +
      '<div class="_ats_section_hint">Drop placeholders and conditional blocks where the cursor is in Word.</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsPlaceholderInput" type="text" placeholder="placeholderName" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsInsertPh">+ Placeholder</button>' +
      '</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsConditionInput" type="text" placeholder="condition (e.g. hasIndemnity)" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsWrapCond">↻ Wrap selection if</button>' +
      '</div>' +
      '<div class="_ats_grid_2" style="margin-top:6px;">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertElse">+ {{else}}</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertEnd">+ {{/if}}</button>' +
      '</div>' +
    '</div>' +

    // Detected tags (from live Word doc)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🔍 Detected in doc <span class="_ats_detected_count" id="atsDetectedCount">0</span></div>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRefreshTags">🔄</button>' +
      '</div>' +
      '<div class="_ats_detected" id="atsDetectedBody"></div>' +
    '</div>' +

    // Logic block tracer — {{#if}} / {{else}} / {{/if}} structure with errors.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🌳 Logic blocks <span class="_ats_detected_count" id="atsLogicCount">0</span></div>' +
      '</div>' +
      '<div class="_ats_section_hint">Traced from <code>{{#if X}}</code> / <code>{{else}}</code> / <code>{{/if}}</code> (and <code>{{#each}}</code>) in the doc. Click a condition to jump to it. Red blocks have errors (unmatched/duplicated).</div>' +
      '<div id="atsLogicTree" class="_ats_logic_tree"></div>' +
    '</div>' +

    // BD prompt tester — uses Build Draft's actual placeholder regex.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🎯 Build Draft prompts</div>' +
      '</div>' +
      '<div class="_ats_section_hint">Exact placeholders Build Draft would prompt for: <code>$![field]</code>, <code>[[field]]</code>, <code>{{field}}</code>. Fill values, then apply to test the substitution flow. Click any chip to jump in Word.</div>' +
      '<div id="atsBdList" class="_ats_bdlist"></div>' +
      '<div style="margin-top:8px;">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsApplyBd" style="width:100%;">⚡ Apply BD prompt values to doc</button>' +
      '</div>' +
    '</div>' +

    // Metadata (collapsible-feeling at the bottom — small, edit-when-needed)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📌 Metadata</div>' +
      '</div>' +
      '<div id="atsMetadataBody"></div>' +
    '</div>';

  // Wire actions
  document.getElementById("atsLoadInto").onclick = _atsLoadIntoDoc;
  document.getElementById("atsSaveFrom").onclick = _atsSaveFromDoc;
  document.getElementById("atsSnap").onclick = function () {
    _atsSnapshot().then(function (ok) {
      if (typeof showToast === "function") showToast(ok ? "📸 Snapshot taken" : "Snapshot failed", ok ? "ok" : "err");
    });
  };
  document.getElementById("atsRestore").onclick = _atsRestore;
  document.getElementById("atsRefreshTags").onclick = function () {
    if (typeof showToast === "function") showToast("⏳ Scanning doc…", "info");
    _atsDetectTagsLive().then(function (tags) {
      if (typeof showToast === "function") showToast("Found " + tags.length + " tag" + (tags.length === 1 ? "" : "s"), "ok");
    });
  };
  document.getElementById("atsInsertPh").onclick = function () {
    var name = (document.getElementById("atsPlaceholderInput").value || "").trim();
    if (!name) {
      if (typeof showToast === "function") showToast("Enter a placeholder name first.", "warn");
      return;
    }
    _atsInsertAtCursor("{" + name + "}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {" + name + "}", "ok");
      _atsDetectTagsLive();
    });
  };
  document.getElementById("atsWrapCond").onclick = function () {
    var cond = (document.getElementById("atsConditionInput").value || "").trim();
    if (!cond) {
      if (typeof showToast === "function") showToast("Enter a condition first.", "warn");
      return;
    }
    _atsWrapSelection("{{#if " + cond + "}}", "{{/if}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Wrapped selection", "ok");
    });
  };
  document.getElementById("atsInsertElse").onclick = function () {
    _atsInsertAtCursor("{{else}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {{else}}", "ok");
    });
  };
  document.getElementById("atsInsertEnd").onclick = function () {
    _atsInsertAtCursor("{{/if}}").then(function () {
      if (typeof showToast === "function") showToast("✓ Inserted {{/if}}", "ok");
    });
  };
  document.getElementById("atsApplyBd").onclick = function () {
    var st = _atsState();
    _atsApplyBdReplacements(st.mockValues).then(function (count) {
      if (typeof showToast === "function") showToast("✓ Replaced " + count + " occurrence" + (count === 1 ? "" : "s"), count ? "ok" : "warn");
      // Refresh detection so the panel shows what's left unfilled.
      _atsDetectTagsLive();
    });
  };

  _atsRenderCurrent();
  _atsRenderDetected();
  _atsRenderBDPrompts();
  _atsRenderLogicTree();
  _atsRenderMetadata();
}

