functions._atsActionNew:
function _atsActionNew() {
  if (!window.eli.ui || !window.eli.ui.prompt) return;
  window.eli.ui.prompt({
    title: "New template",
    message: "Template name:",
    placeholder: "e.g. Service Agreement v2",
    confirmLabel: "Create", cancelLabel: "Cancel",
  }).then(function (name) {
    if (!name || !name.trim()) return;
    var tpl = {
      id: "tpl_" + Date.now(),
      name: name.trim(),
      agreementType: "",
      status: "draft",
      content: "",
      locked: false,
      lastUpdated: Date.now(),
    };
    _atsSaveRow(tpl).then(function () { return _atsLoadAll(); }).then(function (all) {
      _atsState().templates = all;
      _atsState().currentId = tpl.id;
      _atsState().pickerOpen = false;
      _atsRenderAll();
      if (typeof showToast === "function") showToast("Created " + tpl.name, "ok");
    });
  });
}

functions._atsActionDuplicate:
function _atsActionDuplicate() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  var copy = Object.assign({}, tpl, {
    id: tpl.id + "_copy_" + Date.now(),
    name: (tpl.name || tpl.id) + " (copy)",
    status: "draft",
    locked: false,
    lastUpdated: Date.now(),
  });
  _atsSaveRow(copy).then(function () { return _atsLoadAll(); }).then(function (all) {
    _atsState().templates = all;
    _atsState().currentId = copy.id;
    _atsState().pickerOpen = false;
    _atsRenderAll();
    if (typeof showToast === "function") showToast("Duplicated → " + copy.name, "ok");
  });
}

functions._atsActionLock:
function _atsActionLock() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  tpl.locked = !tpl.locked;
  _atsSaveRow(tpl).then(function () { return _atsLoadAll(); }).then(function (all) {
    _atsState().templates = all;
    _atsRenderAll();
    if (typeof showToast === "function") showToast(tpl.locked ? "🔒 Locked" : "🔓 Unlocked", "info");
  });
}

functions._atsActionExport:
function _atsActionExport() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  var blob = new Blob([JSON.stringify(tpl, null, 2)], { type: "application/json" });
  var url = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.href = url; a.download = (tpl.id || "template") + ".json";
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  if (typeof showToast === "function") showToast("Exported", "ok");
}

functions._atsActionDelete:
function _atsActionDelete() {
  var tpl = _atsCurrent();
  if (!tpl) return;
  if (!window.eli.ui || !window.eli.ui.confirm) return;
  window.eli.ui.confirm({
    variant: "danger", icon: "🗑", title: "Delete template?",
    message: "Permanently remove <b>" + _atsEsc(tpl.name || tpl.id) + "</b> from local IDB.",
    confirmLabel: "Delete", cancelLabel: "Cancel",
  }).then(function (ok) {
    if (!ok) return;
    _atsDeleteById(tpl.id).then(function () {
      _atsState().currentId = null;
      return _atsLoadAll();
    }).then(function (all) {
      _atsState().templates = all;
      _atsRenderAll();
      if (typeof showToast === "function") showToast("Deleted", "info");
    });
  });
}

functions._atsActionImport:
function _atsActionImport() {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json,application/json";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0];
    if (!f) return;
    var reader = new FileReader();
    reader.onload = function (ev) {
      try {
        var parsed = JSON.parse(ev.target.result);
        if (!parsed || !parsed.id) throw new Error("missing id");
        return _atsSaveRow(parsed).then(function () { return _atsLoadAll(); }).then(function (all) {
          _atsState().templates = all;
          _atsState().currentId = parsed.id;
          _atsState().pickerOpen = false;
          _atsRenderAll();
          if (typeof showToast === "function") showToast("✓ Imported " + parsed.id, "ok");
        });
      } catch (e2) {
        if (typeof showToast === "function") showToast("Import failed: " + (e2 && e2.message || "unknown"), "err");
      }
    };
    reader.readAsText(f);
  };
  inp.click();
}

