  // Picker head toggles open/closed
  document.getElementById("atsPickerHead").onclick = function () {
    var st = _atsState();
    st.pickerOpen = !st.pickerOpen;
    _atsRenderPicker();
  };

  _atsLoadAll().then(function (all) {
    var st = _atsState();
    st.templates = all;
    // Auto-select the most recently-updated template if nothing's selected.
    if (!st.currentId && all.length) {
      var sorted = all.slice().sort(function (a, b) { return (b.lastUpdated || 0) - (a.lastUpdated || 0); });
      st.currentId = sorted[0].id;
    }
    document.getElementById("atsPickerCount").textContent = all.length + " template" + (all.length === 1 ? "" : "s");
    _atsRenderAll();
    _atsRenderPicker();
    // Initial tag scan (best-effort — fails silently if no doc is ready).
    _atsDetectTagsLive();
  });
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateStudio"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminTemplateStudio !== "function") {
      eli.log.event("tool", "admin_template_studio_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Studio failed to load", "err");
      return;
    }
    try { window.showAdminTemplateStudio(); }
    catch (e) {
      eli.log.event("tool", "admin_template_studio_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_template_studio: _show },
    admin_template_studio: { open: _show },
  });

  eli.log.event("tool", "admin_template_studio_initialized", {});
}

